import asyncio
from playwright.async_api import async_playwright

html_content = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>JS Framework Benchmark Poster</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800&family=JetBrains+Mono:wght@400;700&display=swap');

        :root {
            --bg-color: #0b1120;
            --panel-bg: #1e293b;
            --text-main: #f8fafc;
            --text-muted: #94a3b8;
            --electric-blue: #0ea5e9;
            --teal: #14b8a6;
            --amber: #f59e0b;
            --amber-bg: rgba(245, 158, 11, 0.1);
            --grid-color: rgba(255, 255, 255, 0.05);
        }

        body {
            margin: 0;
            padding: 0;
            font-family: 'Inter', sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            width: 2376px;
            height: 3364px;
            box-sizing: border-box;
            background-image: linear-gradient(var(--grid-color) 1px, transparent 1px),
                              linear-gradient(90deg, var(--grid-color) 1px, transparent 1px);
            background-size: 40px 40px;
            position: relative;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            padding: 120px 140px;
        }

        .header {
            margin-bottom: 80px;
        }

        .header h1 {
            font-size: 110px;
            font-weight: 800;
            margin: 0 0 40px 0;
            line-height: 1.1;
            letter-spacing: -2px;
            color: #ffffff;
        }

        .header p {
            font-size: 42px;
            font-weight: 300;
            color: var(--text-muted);
            max-width: 1800px;
            line-height: 1.4;
            margin: 0;
            border-left: 8px solid var(--electric-blue);
            padding-left: 32px;
        }

        .hero-stats {
            display: flex;
            gap: 60px;
            margin-bottom: 100px;
        }

        .stat-box {
            background: var(--panel-bg);
            border-radius: 24px;
            padding: 60px;
            flex: 1;
            border-top: 6px solid var(--electric-blue);
            box-shadow: 0 20px 40px rgba(0,0,0,0.4);
        }

        .stat-box.teal {
            border-top-color: var(--teal);
        }

        .stat-value {
            font-family: 'JetBrains Mono', monospace;
            font-size: 140px;
            font-weight: 700;
            margin: 0 0 20px 0;
            color: var(--electric-blue);
            line-height: 1;
        }

        .stat-box.teal .stat-value {
            color: var(--teal);
        }

        .stat-label {
            font-size: 40px;
            font-weight: 600;
            margin: 0 0 16px 0;
            color: #ffffff;
        }

        .stat-context {
            font-size: 28px;
            color: var(--text-muted);
            margin: 0;
        }

        .content-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 80px;
            flex: 1;
        }

        /* Timeline spanning the full width or dominating a column */
        .timeline-section {
            grid-column: 1 / 3;
            background: rgba(30, 41, 59, 0.6);
            border-radius: 32px;
            padding: 80px;
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .section-title {
            font-size: 56px;
            font-weight: 800;
            margin: 0 0 60px 0;
            color: #ffffff;
            display: flex;
            align-items: center;
            gap: 24px;
        }

        .section-title::before {
            content: '';
            display: block;
            width: 32px;
            height: 32px;
            background: var(--electric-blue);
            border-radius: 8px;
        }

        .timeline {
            position: relative;
            padding-top: 40px;
        }

        .timeline::after {
            content: '';
            position: absolute;
            left: 0;
            right: 0;
            top: 0;
            height: 8px;
            background: var(--panel-bg);
            border-radius: 4px;
        }

        .timeline-events {
            display: flex;
            justify-content: space-between;
            position: relative;
        }

        .timeline-event {
            width: 14%;
            position: relative;
            padding-top: 60px;
        }

        .timeline-event::before {
            content: '';
            position: absolute;
            top: -4px;
            left: 0;
            width: 24px;
            height: 24px;
            background: var(--teal);
            border-radius: 50%;
            z-index: 2;
        }

        .timeline-event.warning::before {
            background: var(--amber);
            box-shadow: 0 0 20px var(--amber);
        }

        .event-year {
            font-family: 'JetBrains Mono', monospace;
            font-size: 40px;
            font-weight: 700;
            color: #ffffff;
            margin-bottom: 16px;
        }

        .event-chrome {
            font-size: 32px;
            font-weight: 600;
            color: var(--teal);
            margin-bottom: 16px;
        }

        .event-desc {
            font-size: 26px;
            color: var(--text-muted);
            line-height: 1.5;
        }

        .timeline-event.warning .event-chrome {
            color: var(--amber);
        }

        .timeline-event.warning .event-year {
            color: var(--amber);
        }

        .methodology-warning {
            background: var(--amber-bg);
            border: 2px dashed var(--amber);
            border-radius: 24px;
            padding: 60px;
            margin-top: 60px;
        }

        .methodology-warning .section-title {
            color: var(--amber);
        }

        .methodology-warning .section-title::before {
            background: var(--amber);
        }

        .warning-text {
            font-size: 36px;
            color: #ffffff;
            margin-bottom: 40px;
            line-height: 1.5;
        }

        .warning-list {
            font-size: 32px;
            color: var(--text-muted);
            line-height: 1.6;
            margin: 0;
            padding-left: 40px;
        }

        .warning-list li {
            margin-bottom: 20px;
        }

        .bottom-panels {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 80px;
            margin-top: 80px;
        }

        .panel {
            background: var(--panel-bg);
            border-radius: 32px;
            padding: 80px;
            border: 1px solid rgba(255,255,255,0.05);
        }

        .panel .section-title::before {
            background: var(--teal);
        }

        .takeaways-list {
            list-style: none;
            padding: 0;
            margin: 0;
        }

        .takeaways-list li {
            font-size: 32px;
            color: var(--text-main);
            margin-bottom: 40px;
            line-height: 1.5;
            padding-left: 60px;
            position: relative;
        }

        .takeaways-list li::before {
            content: '→';
            position: absolute;
            left: 0;
            color: var(--electric-blue);
            font-weight: bold;
        }

        .takeaways-list li strong {
            color: #ffffff;
        }

        .platform-stat {
            display: flex;
            align-items: center;
            margin-bottom: 40px;
            background: rgba(0,0,0,0.2);
            padding: 30px 40px;
            border-radius: 20px;
            border-left: 6px solid var(--teal);
        }

        .platform-stat.mac { border-left-color: var(--electric-blue); }

        .p-stat-val {
            font-family: 'JetBrains Mono', monospace;
            font-size: 64px;
            font-weight: 700;
            width: 250px;
        }

        .platform-stat.mac .p-stat-val { color: var(--electric-blue); }
        .platform-stat .p-stat-val { color: var(--teal); }

        .p-stat-desc {
            font-size: 32px;
            color: var(--text-muted);
            flex: 1;
        }

        .p-stat-desc strong {
            color: white;
        }
    </style>
</head>
<body>

    <div class="header">
        <h1>JS Framework Benchmark:<br>5 Years of Browser Performance Testing</h1>
        <p>A comprehensive overview of the official JavaScript web framework benchmark spanning Chrome 55 through Chrome 146, tracking how the testing methodology and ecosystem have evolved.</p>
    </div>

    <div class="hero-stats">
        <div class="stat-box">
            <div class="stat-value">60+</div>
            <div class="stat-label">Total Official Benchmark Runs</div>
            <div class="stat-context">From Chrome 55 (2017) to Chrome 146 (2026)</div>
        </div>
        <div class="stat-box teal">
            <div class="stat-value">55 – 146</div>
            <div class="stat-label">Chrome Versions Covered</div>
            <div class="stat-context">Spanning approximately 8 years of browser releases</div>
        </div>
        <div class="stat-box">
            <div class="stat-value">12</div>
            <div class="stat-label">Runs in 2025 Alone</div>
            <div class="stat-context">Chrome 132 through 143, the most active single year</div>
        </div>
    </div>

    <div class="timeline-section">
        <h2 class="section-title">Benchmark Timeline: Chrome 55 → 146</h2>
        <div class="timeline">
            <div class="timeline-events">
                <div class="timeline-event">
                    <div class="event-year">2017–19</div>
                    <div class="event-chrome">v55 – v69</div>
                    <div class="event-desc">Early era; hosted on stefankrause.net. (4 runs)</div>
                </div>
                <div class="timeline-event">
                    <div class="event-year">2020–21</div>
                    <div class="event-chrome">v83 – v96</div>
                    <div class="event-desc">Migrated to GitHub Pages; steady monthly cadence established.</div>
                </div>
                <div class="timeline-event">
                    <div class="event-year">2022</div>
                    <div class="event-chrome">v97 – v108</div>
                    <div class="event-desc">13 runs. First Windows run introduced at Chrome 104.</div>
                </div>
                <div class="timeline-event warning">
                    <div class="event-year">2023</div>
                    <div class="event-chrome">v109 – v120</div>
                    <div class="event-desc"><strong>MAJOR OVERHAUL (v118)</strong><br>Scoring & throttling recalibrated.</div>
                </div>
                <div class="timeline-event">
                    <div class="event-year">2024</div>
                    <div class="event-chrome">v121 – v131</div>
                    <div class="event-desc">Includes 2nd Windows run (v121). Ongoing refinements.</div>
                </div>
                <div class="timeline-event">
                    <div class="event-year">2025</div>
                    <div class="event-chrome">v132 – v143</div>
                    <div class="event-desc">Most active year. Alternating keyed-only vs full runs.</div>
                </div>
                <div class="timeline-event">
                    <div class="event-year">2026</div>
                    <div class="event-chrome">v144 – v146</div>
                    <div class="event-desc">Latest benchmarks. Currently tracking up to v146 on macOS.</div>
                </div>
            </div>
        </div>

        <div class="methodology-warning">
            <h2 class="section-title">Methodology Milestones & Danger Zone</h2>
            <div class="warning-text">
                <strong>⚠️ CROSS-VERSION COMPARISONS ARE UNSAFE.</strong> The benchmark and its driver are constantly developing. Major structural changes introduced in <strong>Chrome 118</strong> mean direct comparisons across this threshold are statistically invalid.
            </div>
            <ul class="warning-list">
                <li><strong>Weighted Geometric Mean (Chrome 118+):</strong> Overall score switched from arithmetic to weighted geometric mean.</li>
                <li><strong>CPU Throttling Adjustment (Chrome 118+):</strong> Throttling factors recalibrated for more realistic load simulation.</li>
                <li><strong>Measurement Fine-Tuning (Chrome 118+):</strong> Ongoing refinements to timing and driver instrumentation.</li>
            </ul>
        </div>
    </div>

    <div class="bottom-panels">
        <div class="panel">
            <h2 class="section-title">Platform & Framework Coverage</h2>

            <div class="platform-stat mac">
                <div class="p-stat-val">>95%</div>
                <div class="p-stat-desc"><strong>macOS (OSX) Dominance</strong><br>The vast majority of runs were executed on macOS, shaping the benchmark's performance characteristics.</div>
            </div>

            <div class="platform-stat">
                <div class="p-stat-val">2</div>
                <div class="p-stat-desc"><strong>Windows Runs Total</strong><br>Only Chrome 104 (2022) and Chrome 121 (2024) have official Windows data.</div>
            </div>

            <div class="platform-stat">
                <div class="p-stat-val">Odd / Even</div>
                <div class="p-stat-desc"><strong>Keyed vs. Non-Keyed Pattern</strong><br>In recent versions (139+), odd Chrome versions often benchmark <em>keyed frameworks only</em>, while even versions include both.</div>
            </div>
        </div>

        <div class="panel">
            <h2 class="section-title">Key Takeaways for Developers</h2>
            <ul class="takeaways-list">
                <li><strong>Compare within the same Chrome version.</strong> Methodology and CPU throttling differ drastically across releases.</li>
                <li><strong>Consult the latest run</strong> (currently Chrome 146) for the most accurate and up-to-date framework standings.</li>
                <li><strong>Understand keyed vs non-keyed modes.</strong> Be aware of the alternating pattern in recent runs before drawing conclusions on framework features.</li>
                <li><strong>Appreciate the scale.</strong> With 60+ data points over 8 years, this is the longest-running and most comprehensive JS framework performance tracker available.</li>
                <li><strong>Embrace the geometric mean.</strong> The shift since Chrome 118 provides a much more balanced overall score than previous arithmetic models.</li>
            </ul>
        </div>
    </div>

</body>
</html>
"""

async def main():
    with open("poster.html", "w") as f:
        f.write(html_content)

    async with async_playwright() as p:
        browser = await p.chromium.launch()
        page = await browser.new_page(viewport={'width': 2376, 'height': 3364})
        await page.goto("file:///app/poster.html")
        # wait a bit for fonts
        await page.wait_for_timeout(2000)
        await page.screenshot(path="/app/output/final_poster.png")
        await browser.close()

if __name__ == "__main__":
    asyncio.run(main())
